import { Controller, Get, HttpCode, Post, Put, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 카드번호 암호화 키. 운영에서는 별도 비밀 관리로 교체한다. (pgcrypto 필요)
const CARD_KEY = 'groupware-card-key-0123456789ab';
// 가정: 카드번호는 숫자 12~19자리
const CARD_NO_PATTERN = /^[0-9]{12,19}$/;
const ROLE = '예산·회계 담당자';

// 같은 카드번호는 항상 같은 암호문이 되도록 결정적 암호화를 쓴다 (중복 검사용)
const ENCRYPT_SQL = "encode(encrypt(convert_to(:cardNo, 'utf8'), convert_to(:cardKey, 'utf8'), 'aes'), 'hex')";

function invalid(message: string): ApiError {
  return new ApiError(422, 'CREDIT_CARD_INVALID', message);
}

function text(value: unknown, label: string, max: number, required: boolean): string {
  if (value === undefined || value === null || value === '') {
    if (required) {
      throw invalid(label + '을(를) 입력하세요.');
    }
    return '';
  }
  if (typeof value !== 'string') {
    throw invalid(label + ' 형식이 올바르지 않습니다.');
  }
  const trimmed = value.trim();
  if (required && trimmed === '') {
    throw invalid(label + '을(를) 입력하세요.');
  }
  if (trimmed.length > max) {
    throw invalid(label + '은(는) ' + max + '자 이하여야 합니다.');
  }
  return trimmed;
}

function viewerIds(raw: unknown): number[] | undefined {
  if (raw === undefined || raw === null) {
    return undefined;
  }
  if (!Array.isArray(raw)) {
    throw invalid('조회 권한 대상 형식이 올바르지 않습니다.');
  }
  const ids: number[] = [];
  for (const item of raw) {
    const id = Number(item);
    if (item === '' || item === null || !Number.isInteger(id) || id <= 0) {
      throw invalid('조회 권한 대상 임직원 ID가 올바르지 않습니다.');
    }
    if (!ids.includes(id)) {
      ids.push(id);
    }
  }
  return ids;
}

// 결정: 마지막 4자리만 보이고 나머지는 *
function maskCardNo(cardNo: unknown): string {
  const s = String(cardNo ?? '');
  if (s.length <= 4) {
    return '*'.repeat(s.length);
  }
  return '*'.repeat(s.length - 4) + s.slice(-4);
}

@Controller('api/v1')
export class FnSfr00206Controller {
  @Post('/credit-cards')
  @HttpCode(200)
  async createCreditCard(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const cardType = text(data['cardType'], '카드 유형', 50, true);
    const cardNo = text(data['cardNo'], '카드번호', 30, true).replace(/[\s-]/g, '');
    if (!CARD_NO_PATTERN.test(cardNo)) {
      throw invalid('카드번호는 숫자 12~19자리여야 합니다.');
    }
    const cardName = text(data['cardName'], '카드명', 100, false);
    const cardDetail = text(data['cardDetail'], '카드 상세 정보', 1000, false);
    const viewers = viewerIds(data['viewerEmployeeIds']) ?? [];

    return transaction(async (db) => {
      for (const id of viewers) {
        const found = await db.query('SELECT employee_id FROM employee WHERE employee_id = CAST(:id AS bigint)', { id });
        if (found.length === 0) {
          throw invalid('존재하지 않는 임직원이 조회 권한 대상에 있습니다.');
        }
      }
      const dup = await db.query(
        'SELECT credit_card_id FROM credit_card WHERE card_no_enc = ' + ENCRYPT_SQL,
        { cardNo, cardKey: CARD_KEY },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'CREDIT_CARD_DUPLICATED', '이미 등록된 카드번호입니다.');
      }
      const rows = await db.query(
        'INSERT INTO credit_card (card_no_enc, card_name, card_type, card_detail, created_at, updated_at) '
          + 'VALUES (' + ENCRYPT_SQL + ', :cardName, :cardType, :cardDetail, now(), now()) '
          + 'RETURNING credit_card_id AS "creditCardId"',
        { cardNo, cardKey: CARD_KEY, cardName: cardName === '' ? null : cardName, cardType, cardDetail: cardDetail === '' ? null : cardDetail },
      );
      const creditCardId = Number(rows[0]['creditCardId']);
      for (const id of viewers) {
        await db.execute(
          'INSERT INTO credit_card_viewer (credit_card_id, employee_id, created_at, updated_at) '
            + 'VALUES (CAST(:creditCardId AS bigint), CAST(:id AS bigint), now(), now())',
          { creditCardId, id },
        );
      }
      return { creditCardId, maskedCardNo: maskCardNo(cardNo) };
    });
  }

  @Put('/credit-cards/:creditCardId')
  async updateCreditCard(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const idText = req.params['creditCardId'];
    const creditCardId = Number(idText);
    if (idText === '' || !Number.isInteger(creditCardId) || creditCardId <= 0) {
      throw new ApiError(404, 'CREDIT_CARD_NOT_FOUND', '신용카드를 찾을 수 없습니다.');
    }
    const cardType = text(data['cardType'], '카드 유형', 50, true);
    const cardName = text(data['cardName'], '카드명', 100, false);
    const cardDetail = text(data['cardDetail'], '카드 상세 정보', 1000, false);
    // 값이 없으면 기존 조회 권한 대상을 그대로 둔다
    const viewers = viewerIds(data['viewerEmployeeIds']);

    return transaction(async (db) => {
      const found = await db.query(
        'SELECT credit_card_id FROM credit_card WHERE credit_card_id = CAST(:creditCardId AS bigint)',
        { creditCardId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'CREDIT_CARD_NOT_FOUND', '신용카드를 찾을 수 없습니다.');
      }
      if (viewers !== undefined) {
        for (const id of viewers) {
          const emp = await db.query('SELECT employee_id FROM employee WHERE employee_id = CAST(:id AS bigint)', { id });
          if (emp.length === 0) {
            throw invalid('존재하지 않는 임직원이 조회 권한 대상에 있습니다.');
          }
        }
      }
      await db.execute(
        'UPDATE credit_card SET card_type = :cardType, card_name = :cardName, card_detail = :cardDetail, updated_at = now() '
          + 'WHERE credit_card_id = CAST(:creditCardId AS bigint)',
        { cardType, cardName: cardName === '' ? null : cardName, cardDetail: cardDetail === '' ? null : cardDetail, creditCardId },
      );
      if (viewers !== undefined) {
        await db.execute(
          'DELETE FROM credit_card_viewer WHERE credit_card_id = CAST(:creditCardId AS bigint)',
          { creditCardId },
        );
        for (const id of viewers) {
          await db.execute(
            'INSERT INTO credit_card_viewer (credit_card_id, employee_id, created_at, updated_at) '
              + 'VALUES (CAST(:creditCardId AS bigint), CAST(:id AS bigint), now(), now())',
            { creditCardId, id },
          );
        }
      }
      return { creditCardId };
    });
  }

  @Get('/credit-cards')
  async listCreditCards(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const pageNo = query['page'] === undefined || query['page'] === '' ? 0 : Number(query['page']);
    let size = query['size'] === undefined || query['size'] === '' ? 20 : Number(query['size']);
    if (!Number.isInteger(pageNo) || pageNo < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '페이지 값이 올바르지 않습니다.');
    }
    if (size > 200) {
      size = 200;
    }
    const cardType = typeof query['cardType'] === 'string' ? (query['cardType'] as string).trim() : '';

    // 가정: 조회 권한 대상이 지정된 카드는 그 대상(현재 사용자)만 보고, 대상이 없는 카드는 담당자 모두가 본다
    const where =
      "WHERE (:cardType = '' OR c.card_type = :cardType) "
      + 'AND (NOT EXISTS (SELECT 1 FROM credit_card_viewer v WHERE v.credit_card_id = c.credit_card_id) '
      + 'OR EXISTS (SELECT 1 FROM credit_card_viewer v WHERE v.credit_card_id = c.credit_card_id '
      + 'AND v.employee_id = CAST(:userId AS bigint)))';

    return transaction(async (db) => {
      const totalRows = await db.query(
        'SELECT COUNT(*) AS "total" FROM credit_card c ' + where,
        { cardType, userId: user.id },
      );
      const rows = await db.query(
        'SELECT c.credit_card_id AS "creditCardId", c.card_type AS "cardType", c.card_name AS "cardName", '
          + 'c.card_detail AS "cardDetail", '
          + "convert_from(decrypt(decode(c.card_no_enc, 'hex'), convert_to(:cardKey, 'utf8'), 'aes'), 'utf8') AS \"cardNo\" "
          + 'FROM credit_card c ' + where + ' ORDER BY c.credit_card_id DESC '
          + 'LIMIT :size OFFSET :offset',
        { cardType, userId: user.id, cardKey: CARD_KEY, size, offset: pageNo * size },
      );
      const items = rows.map((row) => ({
        creditCardId: Number(row['creditCardId']),
        cardType: row['cardType'],
        cardName: row['cardName'],
        cardDetail: row['cardDetail'],
        maskedCardNo: maskCardNo(row['cardNo']),
      }));
      return { items, page: pageNo, size, total: Number(totalRows[0]['total']) };
    });
  }
}

