import { useState } from 'react';
import { Band, DataTable, Drawer, Field, Filters, Form, LookupSelect, NumberInput, Num, Pager, RefName, Select, TextInput, call, useData } from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 20;

export default function FnSfr00206Page({ role, notify }: PageProps) {
  const [cardTypeInput, setCardTypeInput] = useState('');
  const [cardType, setCardType] = useState('');
  const [pageNo, setPageNo] = useState(0);
  const [mode, setMode] = useState<'' | 'create' | 'edit'>('');
  const [editId, setEditId] = useState<number | null>(null);
  const [formType, setFormType] = useState('');
  const [formNo, setFormNo] = useState('');
  const [formName, setFormName] = useState('');
  const [formDetail, setFormDetail] = useState('');
  const [viewers, setViewers] = useState<number[]>([]);
  const [viewersTouched, setViewersTouched] = useState(false);

  const list = useData<Page>(
    () => call<Page>('GET', '/credit-cards', role, undefined, { cardType, page: pageNo, size: SIZE }),
    [cardType, pageNo, role],
  );

  const openCreate = () => {
    setEditId(null);
    setFormType('');
    setFormNo('');
    setFormName('');
    setFormDetail('');
    setViewers([]);
    setViewersTouched(false);
    setMode('create');
  };

  const openEdit = (row: Row) => {
    setEditId(Number(row['creditCardId']));
    setFormType(String(row['cardType'] ?? ''));
    setFormNo('');
    setFormName(String(row['cardName'] ?? ''));
    setFormDetail(String(row['cardDetail'] ?? ''));
    setViewers([]);
    setViewersTouched(false);
    setMode('edit');
  };

  const addViewer = (v: number | string) => {
    const id = Number(v);
    if (v === '' || !Number.isInteger(id)) {
      return;
    }
    setViewersTouched(true);
    setViewers((prev) => (prev.includes(id) ? prev : [...prev, id]));
  };

  const removeViewer = (id: number) => {
    setViewersTouched(true);
    setViewers((prev) => prev.filter((x) => x !== id));
  };

  const submit = async () => {
    if (formType.trim() === '') {
      throw new Error('카드 유형을 입력하세요.');
    }
    if (mode === 'create') {
      if (formNo.trim() === '') {
        throw new Error('카드번호를 입력하세요.');
      }
      await call('POST', '/credit-cards', role, {
        cardType: formType,
        cardNo: formNo,
        cardName: formName,
        cardDetail: formDetail,
        viewerEmployeeIds: viewers,
      });
      notify('신용카드를 등록했습니다.');
    } else {
      const body: Row = { cardType: formType, cardName: formName, cardDetail: formDetail };
      if (viewersTouched) {
        body['viewerEmployeeIds'] = viewers;
      }
      await call('PUT', '/credit-cards/' + editId, role, body);
      notify('신용카드를 수정했습니다.');
    }
    setMode('');
    list.reload();
  };

  const rows = list.data?.items ?? [];
  const total = list.data?.total ?? 0;

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>등록 카드</h2>
        <strong><Num value={total} /></strong>
      </section>
      <section className="box span-12">
        <h2>신용카드 목록</h2>
        <Filters
          onSearch={() => {
            setPageNo(0);
            setCardType(cardTypeInput.trim());
          }}
          onReset={() => {
            setCardTypeInput('');
            setCardType('');
            setPageNo(0);
          }}
        >
          <Field label="카드 유형">
            <TextInput value={cardTypeInput} onChange={setCardTypeInput} />
          </Field>
        </Filters>
        <Band total={total}>
          <button type="button" onClick={openCreate}>카드 등록</button>
        </Band>
        {list.error !== '' && <p>{list.error}</p>}
        <DataTable
          rows={rows}
          empty="등록된 신용카드가 없습니다."
          columns={[
            { key: 'cardType', label: '카드 유형' },
            { key: 'cardName', label: '카드명' },
            { key: 'maskedCardNo', label: '마스킹된 카드번호' },
            { key: 'cardDetail', label: '카드 상세 정보' },
            {
              key: 'edit',
              label: '관리',
              render: (row: Row) => (
                <button type="button" onClick={() => openEdit(row)}>수정</button>
              ),
            },
          ]}
        />
        <Pager page={pageNo} size={SIZE} total={total} onPage={setPageNo} />
      </section>
      {mode !== '' && (
        <Drawer title={mode === 'create' ? '신용카드 등록' : '신용카드 수정'} onClose={() => setMode('')}>
          <Form onSubmit={submit} submit={mode === 'create' ? '등록' : '저장'}>
            <Field label="카드 유형" required>
              <TextInput value={formType} onChange={setFormType} placeholder="예: 법인카드" />
            </Field>
            {mode === 'create' && (
              <Field label="카드번호" required hint="저장 시 암호화되고 화면에는 마스킹되어 보입니다.">
                <TextInput value={formNo} onChange={setFormNo} />
              </Field>
            )}
            <Field label="카드명">
              <TextInput value={formName} onChange={setFormName} />
            </Field>
            <Field label="카드 상세 정보" wide>
              <TextInput value={formDetail} onChange={setFormDetail} multiline />
            </Field>
            <Field
              label="조회 권한 대상 임직원"
              wide
              hint={mode === 'edit' ? '대상을 바꾸면 지정한 목록으로 교체됩니다. 바꾸지 않으면 기존 대상이 유지됩니다.' : undefined}
            >
              <div>
                <LookupSelect table="employee" role={role} value="" onChange={addViewer} placeholder="임직원 추가" />
                {viewers.map((id) => (
                  <div key={id}>
                    <RefName table="employee" role={role} value={id} />
                    <button type="button" onClick={() => removeViewer(id)}>삭제</button>
                  </div>
                ))}
              </div>
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
